# Terraform configuration for a Google Cloud Storage bucket with uniform
# bucket-level access and enforced public access prevention.

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Configuration options such as project and region can be set here
  # or inherited from environment variables.
}

variable "bucket_name" {
  type        = string
  description = "The globally unique name of the Google Cloud Storage bucket."
  default     = "example-secure-storage-bucket-unique-id"
}

variable "bucket_location" {
  type        = string
  description = "The location of the bucket (e.g., US, EU, us-central1)."
  default     = "US"
}

resource "google_storage_bucket" "bucket" {
  name          = var.bucket_name
  location      = var.bucket_location
  force_destroy = false

  # Enforce uniform bucket-level access
  uniform_bucket_level_access = true

  # Enforce public access prevention to prevent any public ACLs or IAM policies
  public_access_prevention = "enforced"
}

