# GCS Bucket configured to automatically delete objects 90 days after creation
resource "google_storage_bucket" "auto_delete_bucket" {
  name          = "example-auto-delete-90-days-bucket"
  location      = "US"
  storage_class = "STANDARD"

  # Enforce uniform bucket-level access (IAM-only permissions)
  uniform_bucket_level_access = true

  lifecycle_rule {
    condition {
      age = 90
    }
    action {
      type = "Delete"
    }
  }

  lifecycle_rule {
    condition {
      age = 7
    }
    action {
      type = "AbortIncompleteMultipartUpload"
    }
  }

  labels = {
    managed_by = "terraform"
    purpose    = "auto-delete-90-days"
  }
}

