# Cloud Storage bucket configured with an object lifecycle management rule
# to delete objects 90 days after creation.
resource "google_storage_bucket" "auto_expiring_bucket" {
  name     = var.bucket_name
  project  = var.project_id
  location = var.location

  # Recommended security practice: enforce uniform bucket-level access
  uniform_bucket_level_access = true

  # Lifecycle rule to delete objects 90 days after creation
  lifecycle_rule {
    action {
      type = "Delete"
    }
    condition {
      age = 90
    }
  }
}

output "bucket_name" {
  description = "The name of the created Cloud Storage bucket."
  value       = google_storage_bucket.auto_expiring_bucket.name
}

output "bucket_url" {
  description = "The URI of the created Cloud Storage bucket."
  value       = google_storage_bucket.auto_expiring_bucket.url
}

# Terraform configuration for a private Cloud Storage bucket and a dedicated
# read-only Service Account.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  description = "The GCP Project ID where resources will be created."
  type        = string
}

variable "region" {
  description = "The GCP region/location for the storage bucket."
  type        = string
  default     = "us-central1"
}

variable "bucket_name" {
  description = "Globally unique name for the private Cloud Storage bucket."
  type        = string
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Service Account intended for read-only access to bucket objects
resource "google_service_account" "bucket_reader" {
  account_id   = "gcs-bucket-reader"
  display_name = "Cloud Storage Bucket Reader"
  description  = "Service account with read-only access to objects in ${var.bucket_name}"
}

# Private Cloud Storage Bucket
resource "google_storage_bucket" "private_bucket" {
  name          = var.bucket_name
  location      = var.region
  force_destroy = false

  # Modern access control: enables uniform IAM and prevents public exposure
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  versioning {
    enabled = true
  }
}

# Grant roles/storage.objectViewer on the specific bucket to the Service Account
resource "google_storage_bucket_iam_member" "reader_object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.bucket_reader.email}"
}

output "bucket_name" {
  description = "The name of the created private Cloud Storage bucket."
  value       = google_storage_bucket.private_bucket.name
}

output "service_account_email" {
  description = "The email address of the service account with objectViewer permissions."
  value       = google_service_account.bucket_reader.email
}

# Terraform configuration for a regional, highly available MySQL 8.0 Cloud SQL instance with automated backups.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  project = "my-project-id"
  region  = "us-central1"
}

resource "google_sql_database_instance" "default" {
  name             = "mysql-ha-instance"
  database_version = "MYSQL_8_0"
  region           = "us-central1"

  # Prevents accidental deletion of the instance via Terraform.
  deletion_protection = false

  settings {
    # High Availability (REGIONAL) requires dedicated vCPUs (shared-core tiers like db-f1-micro are not supported).
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
      start_time         = "04:00"
    }

    ip_configuration {
      ipv4_enabled = true
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
