      version = "~> 8.0"
    }
  }
}

provider "google" {
  # Default project and region can also be supplied via environment variables
}

resource "google_sql_database_instance" "mysql_ha" {
  name                = "mysql-8-ha-instance"
  database_version    = "MYSQL_8_0"
  region              = "us-central1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    # Secure default: disable public IPv4 access
    ip_configuration {
      ipv4_enabled = false
    }
  }
}

terraform {
