}

provider "google" {
  project = "my-project-id"
  region  = "us-central1"
}

# VPC Network required for Cloud SQL private IP connectivity
resource "google_compute_network" "vpc" {
  name                    = "sql-private-vpc"
  auto_create_subnetworks = false
}

# Subnet for general resources within the VPC
resource "google_compute_subnetwork" "subnet" {
  name          = "sql-private-subnet"
  ip_cidr_range = "10.0.0.0/24"
  region        = "us-central1"
  network       = google_compute_network.vpc.id
}

# Reserved internal IP address range for Google Private Services Access
resource "google_compute_global_address" "private_ip_range" {
  name          = "private-ip-range"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.vpc.id
}

# Private Service Access connection to Google services VPC
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.vpc.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_range.name]
}

# PostgreSQL Cloud SQL Instance with private IP only and deletion protection enabled
resource "google_sql_database_instance" "postgres" {
  name             = "postgres-private-instance"
  database_version = "POSTGRES_15"
  region           = "us-central1"

  # Enforce deletion protection
  deletion_protection = true

  depends_on = [google_service_networking_connection.private_vpc_connection]

  settings {
    tier = "db-custom-1-3840"

    ip_configuration {
      # Disable public IPv4 assignment
      ipv4_enabled    = false
      private_network = google_compute_network.vpc.id
    }
  }
}

