# Terraform configuration for a PostgreSQL 15 Cloud SQL instance
# with the db-custom-2-8192 machine tier.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

