  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy the Cloud SQL instance in."
  default     = "my-project-id"
}

variable "region" {
  type        = string
  description = "The GCP region for the Cloud SQL instance."
  default     = "us-central1"
}

# Random suffix to avoid name collisions upon instance deletion/recreation
resource "random_id" "db_name_suffix" {
  byte_length = 4
}

resource "google_sql_database_instance" "postgres" {
  name             = "pg15-instance-${random_id.db_name_suffix.hex}"
  database_version = "POSTGRES_15"
  region           = var.region

  # Set to false to allow terraform destroy to remove the instance
  deletion_protection = false

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"
    disk_size         = 20
    disk_type         = "PD_SSD"
    disk_autoresize   = true

    backup_configuration {
      enabled                        = true
      start_time                     = "03:00"
      point_in_time_recovery_enabled = true
      transaction_log_retention_days = 7
    }

    ip_configuration {
      ipv4_enabled = true
    }

    insights_config {
      query_insights_enabled = true
    }
  }
}

output "instance_name" {
  description = "The name of the Cloud SQL database instance."
  value       = google_sql_database_instance.postgres.name
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL database instance."
  value       = google_sql_database_instance.postgres.connection_name
}

output "public_ip_address" {
  description = "The first public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.postgres.public_ip_address
}

