resource "google_compute_network" "custom_network" {
  name                    = "custom-vpc-network"
  auto_create_subnetworks = false
}

# Firewall rule allowing inbound TCP port 22 (SSH) strictly from 203.0.113.0/24
resource "google_compute_firewall" "allow_ssh_restricted" {
  name        = "allow-ssh-restricted"
  network     = google_compute_network.custom_network.name
  description = "Allow inbound SSH access from authorized CIDR 203.0.113.0/24 only"
  direction   = "INGRESS"
  priority    = 1000

  source_ranges = ["203.0.113.0/24"]

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  log_config {
    metadata = "INCLUDE_ALL_METADATA"
  }
}

# Terraform configuration to create a Cloud Router and Cloud NAT in asia-south1

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

# VPC Network to host the private resources and router
resource "google_compute_network" "vpc" {
  name                    = "vpc-asia-south1"
  auto_create_subnetworks = false
}

# Subnetwork for private VMs in asia-south1
resource "google_compute_subnetwork" "subnet" {
  name                     = "subnet-asia-south1"
  region                   = "asia-south1"
  ip_cidr_range            = "10.0.1.0/24"
  network                  = google_compute_network.vpc.id
  private_ip_google_access = true
}

# Cloud Router in asia-south1
resource "google_compute_router" "router" {
  name    = "router-asia-south1"
  region  = "asia-south1"
  network = google_compute_network.vpc.id
}

# Cloud NAT for outbound internet connectivity for private VMs
resource "google_compute_router_nat" "nat" {
  name                               = "nat-asia-south1"
  router                             = google_compute_router.router.name
  region                             = google_compute_router.router.region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  log_config {
    enable = true
    filter = "ERRORS_ONLY"
  }
}

