data "google_project" "current" {}

# Main Pub/Sub topic receiving incoming messages
resource "google_pubsub_topic" "main" {
  name = "main-topic"
}

# Dead-letter Pub/Sub topic to capture messages that fail delivery
resource "google_pubsub_topic" "dead_letter" {
  name = "dead-letter-topic"
}

# The Cloud Pub/Sub service agent needs roles/pubsub.publisher on the dead-letter topic
resource "google_pubsub_topic_iam_member" "pubsub_dead_letter_publisher" {
  topic  = google_pubsub_topic.dead_letter.name
  role   = "roles/pubsub.publisher"
  member = "serviceAccount:service-${data.google_project.current.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

# Main subscription configured with a dead-letter policy (5 attempts)
resource "google_pubsub_subscription" "main" {
  name  = "main-subscription"
  topic = google_pubsub_topic.main.id

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dead_letter.id
    max_delivery_attempts = 5
  }

  # Ensure the service agent has publisher permissions before dead-letter policy creation
  depends_on = [
    google_pubsub_topic_iam_member.pubsub_dead_letter_publisher
  ]
}

# The Cloud Pub/Sub service agent also needs roles/pubsub.subscriber on the source subscription
resource "google_pubsub_subscription_iam_member" "pubsub_subscriber" {
  subscription = google_pubsub_subscription.main.name
  role         = "roles/pubsub.subscriber"
  member       = "serviceAccount:service-${data.google_project.current.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

