      version = ">= 3.5.0"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy the Cloud SQL instance in."
}

variable "region" {
  type        = string
  description = "The region for the Cloud SQL instance."
  default     = "us-central1"
}

variable "office_vpn_cidr" {
  type        = string
  description = "Public CIDR range of the office VPN allowed to connect directly to the database."
  default     = "198.51.100.0/24" # Replace with actual office VPN public IP range
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Unique suffix for instance naming to avoid collisions
resource "random_id" "db_name_suffix" {
  byte_length = 4
}

# Cloud SQL MySQL Instance with Public IPv4 and Authorized Networks
resource "google_sql_database_instance" "mysql_instance" {
  name                = "mysql-public-${random_id.db_name_suffix.hex}"
  database_version    = "MYSQL_8_0"
  region              = var.region
  deletion_protection = false

  settings {
    tier              = "db-custom-2-7680" # 2 vCPU, 7.5 GB RAM
    availability_type = "ZONAL"
    disk_size         = 50
    disk_type         = "PD_SSD"
    disk_autoresize   = true

    ip_configuration {
      # Enables public IPv4 allocation
      ipv4_enabled = true

      # Enforce SSL/TLS encryption for incoming public connections
      ssl_mode = "ENCRYPTED_ONLY"

      # Whitelist the office VPN CIDR
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
      start_time         = "04:00"
    }
  }
}

