resource "google_sql_database" "default_db" {
  name     = "appdb"
  instance = google_sql_database_instance.mysql_instance.name
  charset  = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

# Generate a secure password for the database user
resource "random_password" "db_user_password" {
  length  = 24
  special = true
}

# Application User configured to connect from the allowed network
resource "google_sql_user" "app_user" {
  name     = "appuser"
  instance = google_sql_database_instance.mysql_instance.name
  host     = "%"
  password = random_password.db_user_password.result
}

# Outputs for connection details
output "instance_public_ip" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.connection_name
}

output "database_user" {
  description = "The username created for direct access."
  value       = google_sql_user.app_user.name
}

output "database_password" {
  description = "The auto-generated password for the database user."
  value       = random_password.db_user_password.result
  sensitive   = true
}

